package handler

import (
	"io"
	"net"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
	"sync"
	"time"

	"gonx/internal/logging"
	"gonx/internal/upstream"
	"gonx/internal/vars"
)

// InternalErrorHeader marks responses generated by gonx itself (not the
// upstream) so error_page interception can distinguish them, mirroring
// proxy_intercept_errors off. It is stripped before reaching the client.
const InternalErrorHeader = "X-Gonx-Internal"

// HeaderPair is one proxy_set_header directive with its value pre-parsed.
type HeaderPair struct {
	Name  string
	Value *vars.Template
}

// CookieRewrite is one proxy_cookie_path prefix replacement.
type CookieRewrite struct {
	From, To string
}

// RedirectRewrite is one proxy_redirect prefix replacement applied to the
// backend's Location header. From "off" disables rewriting entirely and
// From "default" expands to proxy_pass URL → location prefix.
type RedirectRewrite struct {
	From, To string
}

// ProxyOptions carries per-location proxy settings.
type ProxyOptions struct {
	Prefix         string
	Headers        []HeaderPair
	Cookies        []CookieRewrite
	Redirects      []RedirectRewrite // empty = nginx's implicit "default"
	HideHeaders    []string          // proxy_hide_header, on top of defaults
	PassHeaders    []string          // proxy_pass_header, re-enables defaults
	ConnectTimeout time.Duration     // 0 → 60s (proxy_connect_timeout default)
	ReadTimeout    time.Duration     // 0 → 60s (proxy_read_timeout default)
	Keepalive      int               // idle keep-alive conns to backend; 0 → 16 default
}

// defaultHiddenHeaders mirrors nginx: internal X-Accel-* plus Date/Server,
// which the front server re-issues itself.
var defaultHiddenHeaders = []string{
	"Date", "Server", "X-Accel-Expires", "X-Accel-Redirect",
	"X-Accel-Limit-Rate", "X-Accel-Buffering", "X-Accel-Charset",
}

// NewProxy builds the handler behind proxy_pass. If the target host names a
// configured upstream, requests are balanced across its backends with retry
// on connection failure.
func NewProxy(rawURL string, opts ProxyOptions, pools map[string]upstream.Pool, errlog *logging.ErrorLog) (http.Handler, error) {
	prefix, headers, cookies := opts.Prefix, opts.Headers, opts.Cookies
	connectTimeout := opts.ConnectTimeout
	if connectTimeout <= 0 {
		connectTimeout = 60 * time.Second
	}
	readTimeout := opts.ReadTimeout
	if readTimeout <= 0 {
		readTimeout = 60 * time.Second
	}
	target, err := url.Parse(rawURL)
	if err != nil {
		return nil, err
	}
	// an upstream reference is a bare name without port, e.g. http://backend
	var pool upstream.Pool
	if target.Port() == "" {
		pool = pools[target.Hostname()]
	}

	// nginx: proxy_pass with a URI replaces the matched location prefix
	replaceURI := target.Path != "" && prefix != ""
	director := func(req *http.Request) {
		// resolve proxy_set_header values against the request before any
		// defaults ($host must see the original client Host, not the target)
		headerVals := make([]string, len(headers))
		for i, hp := range headers {
			headerVals[i] = hp.Value.Expand(vars.Request(req))
		}
		req.URL.Scheme = target.Scheme
		req.URL.Host = target.Host
		if replaceURI {
			rest := strings.TrimPrefix(req.URL.Path, strings.TrimSuffix(prefix, "/"))
			req.URL.Path = joinPath(target.Path, rest)
		}
		// nginx default: proxy_set_header Host $proxy_host
		req.Host = target.Host
		if ip := clientIP(req.RemoteAddr); ip != "" {
			req.Header.Set("X-Real-IP", ip)
		}
		proto := "http"
		if req.TLS != nil {
			proto = "https"
		}
		req.Header.Set("X-Forwarded-Proto", proto)
		for i, hp := range headers {
			v := headerVals[i]
			switch strings.ToLower(hp.Name) {
			case "host":
				if v != "" {
					req.Host = v
				}
			case "x-forwarded-for":
				// ReverseProxy already appends the client address, which is
				// exactly what $proxy_add_x_forwarded_for produces
			default:
				if v == "" {
					// nginx drops a header whose value expands to empty
					req.Header.Del(hp.Name)
				} else {
					req.Header.Set(hp.Name, v)
				}
			}
		}
		if _, ok := req.Header["User-Agent"]; !ok {
			// keep the stdlib from injecting its default User-Agent
			req.Header.Set("User-Agent", "")
		}
		if pool == nil {
			vars.RecordUpstream(req, target.Host)
		}
	}

	// 组装响应处理：隐藏头 → Set-Cookie 路径改写 → Location 重定向改写
	hidden := map[string]bool{}
	for _, h := range defaultHiddenHeaders {
		hidden[http.CanonicalHeaderKey(h)] = true
	}
	for _, h := range opts.HideHeaders {
		hidden[http.CanonicalHeaderKey(h)] = true
	}
	for _, h := range opts.PassHeaders {
		delete(hidden, http.CanonicalHeaderKey(h))
	}

	// proxy_redirect：无指令 → 隐式 default；"off" → 关闭；显式规则按序匹配
	var redirects []RedirectRewrite
	redirectOff := false
	src := opts.Redirects
	if len(src) == 0 && prefix != "" {
		src = []RedirectRewrite{{From: "default"}}
	}
	for _, rr := range src {
		switch rr.From {
		case "off":
			redirectOff = true
		case "default":
			if prefix != "" {
				redirects = append(redirects, RedirectRewrite{From: rawURL, To: prefix})
			}
		default:
			redirects = append(redirects, rr)
		}
	}
	if redirectOff {
		redirects = nil
	}

	modifyResponse := func(resp *http.Response) error {
		for h := range hidden {
			resp.Header.Del(h)
		}
		if len(cookies) > 0 {
			sc := resp.Header["Set-Cookie"]
			for i, v := range sc {
				sc[i] = rewriteCookiePath(v, cookies)
			}
		}
		if loc := resp.Header.Get("Location"); loc != "" {
			for _, rr := range redirects {
				if strings.HasPrefix(loc, rr.From) {
					resp.Header.Set("Location", rr.To+loc[len(rr.From):])
					break
				}
			}
		}
		return nil
	}

	idlePerHost := 16
	if opts.Keepalive > 0 {
		idlePerHost = opts.Keepalive
	}
	var transport http.RoundTripper = &http.Transport{
		DialContext: (&net.Dialer{
			Timeout:   connectTimeout,
			KeepAlive: 30 * time.Second,
		}).DialContext,
		ResponseHeaderTimeout: readTimeout,
		MaxIdleConns:          100,
		MaxIdleConnsPerHost:   idlePerHost,
		IdleConnTimeout:       90 * time.Second,
	}
	if pool != nil {
		transport = &retryTransport{pool: pool, base: transport, errlog: errlog}
	}

	return &httputil.ReverseProxy{
		Director:       director,
		Transport:      transport,
		ModifyResponse: modifyResponse,
		ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
			errlog.Logf(logging.LevelError, "proxy error for %s %s: %v", r.Method, r.URL.Path, err)
			// marks the 502 as gonx-generated so error_page may intercept it
			w.Header().Set(InternalErrorHeader, "1")
			w.Header().Set("Content-Type", "text/plain; charset=utf-8")
			w.WriteHeader(http.StatusBadGateway)
			io.WriteString(w, "502 Bad Gateway\n")
		},
	}, nil
}

// retryTransport picks a backend per attempt and fails over on connection
// errors, like a minimal proxy_next_upstream.
type retryTransport struct {
	pool   upstream.Pool
	base   http.RoundTripper
	errlog *logging.ErrorLog
}

func (t *retryTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	tries := len(t.pool.Backends())
	if tries < 1 {
		tries = 1
	}
	key := req.Header.Get("X-Real-IP") // set by the director, feeds ip_hash
	var lastErr error
	for i := 0; i < tries; i++ {
		b, err := t.pool.Next(key)
		if err != nil {
			if lastErr != nil {
				return nil, lastErr
			}
			return nil, err
		}
		r2 := req.Clone(req.Context())
		r2.URL.Host = b.Addr
		resp, err := t.base.RoundTrip(r2)
		if err == nil {
			t.pool.MarkUp(b)
			vars.RecordUpstream(req, b.Addr)
			resp.Body = &releaseOnClose{ReadCloser: resp.Body, release: func() { t.pool.Release(b) }}
			return resp, nil
		}
		t.pool.Release(b)
		lastErr = err
		t.pool.MarkDown(b)
		t.errlog.Logf(logging.LevelWarn, "upstream %s failed: %v", b.Addr, err)
		if req.Body != nil && req.Body != http.NoBody {
			// the body may be partially consumed; retrying would corrupt it
			break
		}
	}
	return nil, lastErr
}

// releaseOnClose returns the backend to the pool when the response body is
// fully consumed, keeping least_conn's active counts accurate.
type releaseOnClose struct {
	io.ReadCloser
	release func()
	once    sync.Once
}

func (b *releaseOnClose) Close() error {
	b.once.Do(b.release)
	return b.ReadCloser.Close()
}

// rewriteCookiePath applies proxy_cookie_path prefix replacements to one
// Set-Cookie header value.
func rewriteCookiePath(header string, rws []CookieRewrite) string {
	parts := strings.Split(header, ";")
	for i, p := range parts {
		t := strings.TrimSpace(p)
		if len(t) < 5 || !strings.EqualFold(t[:5], "path=") {
			continue
		}
		val := t[5:]
		for _, rw := range rws {
			if strings.HasPrefix(val, rw.From) {
				parts[i] = " Path=" + rw.To + strings.TrimPrefix(val, rw.From)
				break
			}
		}
	}
	return strings.Join(parts, ";")
}

func joinPath(a, b string) string {
	switch {
	case b == "":
		return a
	case strings.HasSuffix(a, "/") && strings.HasPrefix(b, "/"):
		return a + b[1:]
	case !strings.HasSuffix(a, "/") && !strings.HasPrefix(b, "/"):
		return a + "/" + b
	}
	return a + b
}

func clientIP(remoteAddr string) string {
	if h, _, err := net.SplitHostPort(remoteAddr); err == nil {
		return h
	}
	return remoteAddr
}
